function saveJson(data:unknown,name:string){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function SvgShape({s,selected,onSelect,onBegin}:{s:VectorShape;selected:boolean;onSelect:()=>void;onBegin:(e:PointerEvent<SVGElement>,id:string)=>void}){const shared={fill:s.texture?`url(#${texturePatternId(s.texture,s.fill)})`:s.fill,stroke:selected?'#72b5ff':s.stroke,strokeWidth:selected?Math.max(s.strokeWidth,3):s.strokeWidth,opacity:s.opacity,strokeLinejoin:(s.strokeLineJoin||'round') as 'round'|'miter'|'bevel',strokeLinecap:(s.strokeLineCap||'round') as 'round'|'butt'|'square',transform:`rotate(${s.rotation} ${s.x+s.width/2} ${s.y+s.height/2})`,onPointerDown:(e:PointerEvent<SVGElement>)=>{e.stopPropagation();onSelect();onBegin(e,s.id);}};switch(s.type){case 'ellipse':return <ellipse cx={s.x+s.width/2} cy={s.y+s.height/2} rx={s.width/2} ry={s.height/2} {...shared}/>;case 'polygon':return <polygon points={s.points} {...shared}/>;case 'path':return <path d={s.d} {...shared}/>;default:return <rect x={s.x} y={s.y} width={s.width} height={s.height} rx={s.radius??5} {...shared}/>;}}
function Preview({art,small=false}:{art:Artwork;small?:boolean}){return <svg viewBox="0 0 512 512" className={small?'art-thumb':'art-canvas-svg'} aria-label={art.name} xmlns="http://www.w3.org/2000/svg"><g dangerouslySetInnerHTML={{__html:textureDefs(art.shapes.filter(s=>s.texture).map(s=>({texture:s.texture!,fill:s.fill})))}}/>{art.shapes.map(s=><g key={s.id} dangerouslySetInnerHTML={{__html:shapeMarkup(s)}}/>)}</svg>}
export default function App(){const s=useStudio();const project=s.projects.find(p=>p.id===s.activeProjectId);const art=project?.artworks.find(a=>a.id===s.activeArtworkId);const shape=art?.shapes.find(x=>x.id===s.selectedShapeId);const [tab,setTab]=useState<'create'|'style'|'library'>('create');const [prompt,setPrompt]=useState('Espada medieval com lâmina de ferro e cabo de madeira');const [category,setCategory]=useState('weapons');const [artName,setArtName]=useState('Espada de Ferro');const [inputMode,setInputMode]=useState<'prompt'|'json'>('prompt');const [json,setJson]=useState('{\n  "shapes": [\n    {"type":"rect","name":"Corpo","x":150,"y":120,"width":210,"height":260,"fill":"#8B6545"},\n    {"type":"ellipse","name":"Emblema","x":206,"y":185,"width":100,"height":100,"fill":"#E7C990"}\n  ]\n}');const [provider,setProvider]=useState<GeneratorId>('local-demo');const [multiIds,setMultiIds]=useState<string[]>([]);const [nodeMode,setNodeMode]=useState(false);const [transformMode,setTransformMode]=useState(false);const [activeNodes,setActiveNodes]=useState<number[]>([]);const [snapGrid,setSnapGrid]=useState(false);const [mirrorHandles,setMirrorHandles]=useState(true);const [nodeUndo,setNodeUndo]=useState<string[]>([]);const [nodeRedo,setNodeRedo]=useState<string[]>([]);const [busy,setBusy]=useState(false);const [componentCategory,setComponentCategory]=useState('Ornamentos');const [componentTags,setComponentTags]=useState('');const [componentName,setComponentName]=useState('Novo componente');const [componentSearch,setComponentSearch]=useState('');const [componentScale,setComponentScale]=useState(1);const [componentRotation,setComponentRotation]=useState(0);const [socketName,setSocketName]=useState('mão direita');const [socketX,setSocketX]=useState(256);const [socketY,setSocketY]=useState(256);const [componentSocket,setComponentSocket]=useState('');const [componentLinked,setComponentLinked]=useState(true);const [componentFlip,setComponentFlip]=useState(false);const [sharedGeometry,setSharedGeometry]=useState(true);const [baseArtworkId,setBaseArtworkId]=useState('');const [collectionPreset,setCollectionPreset]=useState('swords');const [collectionMaterials,setCollectionMaterials]=useState<string[]>(['Ferro','Ouro','Cristal']);const [collectionRarities,setCollectionRarities]=useState<string[]>(['Comum','Raro','Épico']);const [collectionPrompt,setCollectionPrompt]=useState('');const [collectionProgress,setCollectionProgress]=useState('');const [batchText,setBatchText]=useState('Espada curta\nMachado de batalha\nEscudo de bronze');const [batchMessage,setBatchMessage]=useState('');const [atlasSize,setAtlasSize]=useState(256);const [atlasColumns,setAtlasColumns]=useState(4);const [atlasPadding,setAtlasPadding]=useState(2);const [editPrompt,setEditPrompt]=useState('');const [editOnlySelected,setEditOnlySelected]=useState(false);const [editProposal,setEditProposal]=useState<EditProposal|null>(null);const [editOriginal,setEditOriginal]=useState<Artwork|null>(null);const [editUndo,setEditUndo]=useState<Artwork|null>(null);const [message,setMessage]=useState('');const [styleText,setStyleText]=useState('');const [styleErrors,setStyleErrors]=useState<string[]>([]);const [zoom,setZoom]=useState(100);const [showGrid,setShowGrid]=useState(true);const [transparent,setTransparent]=useState(true);const [pngSize,setPngSize]=useState(512);const [modal,setModal]=useState<'project'|'styles'|null>(null);const [newProjectName,setNewProjectName]=useState('Novo projeto');const [presetIndex,setPresetIndex]=useState(0);const importRef=useRef<HTMLInputElement>(null);const nodeDragRef=useRef<{id:string;index:number;startD:string}|null>(null);const transformRef=useRef<{id:string;mode:'resize'|'rotate';startX:number;startY:number;original:VectorShape}|null>(null);const dragRef=useRef<{id:string;x:number;y:number;startX:number;startY:number;origins:Record<string,{x:number;y:number}>}|null>(null);
const style=useMemo(()=>project?resolvedStyle(project,category,art):defaultStyle,[project,category,art]);
const notify=(text:string)=>{setMessage(text);setTimeout(()=>setMessage(''),4200)};
const generate=async()=>{if(!project)return;setBusy(true);try{const parsed=inputMode==='json'?JSON.parse(json):undefined;const result=await createArtworkWithProvider(artName||'Nova arte',prompt,category,style,inputMode==='json'?'local-demo':provider,parsed,project.artworks);s.addArtwork(result);setTab('create');notify('Arte criada com camadas editáveis.');}catch(e){notify(`Erro: ${e instanceof Error?e.message:String(e)}`)}finally{setBusy(false)}};
const generateBatch=async()=>{if(!project||busy)return;let prompts:string[];try{prompts=parseBatchLines(batchText);}catch(e){notify(String(e));return;}if(!prompts.length)return;setBusy(true);let completed=0;try{for(const item of prompts){const newArt=await createArtworkWithProvider(item,item,category,style,provider,undefined,project.artworks);s.addArtwork(newArt);completed++;setBatchMessage(completed+' / '+prompts.length);}notify('Lote concluído: '+completed+' arte(s).');}catch(e){notify('Lote interrompido após '+completed+' artes: '+String(e));}finally{setBusy(false);}};
const generateCollection=async()=>{if(!project||busy)return;const preset=templatePresets.find(p=>p.id===collectionPreset);if(!preset)return;let entries:ReturnType<typeof planCollection>;try{entries=planCollection({...preset,basePrompt:collectionPrompt.trim()||preset.basePrompt,materials:collectionMaterials,rarities:collectionRarities as typeof preset.rarities});}catch(e){notify('Template inválido: '+String(e));return;}setBusy(true);let completed=0;try{let base=project.artworks.find(a=>a.id===baseArtworkId);if(sharedGeometry&&!base){base=await createArtworkWithProvider(preset.name,collectionPrompt.trim()||preset.basePrompt,preset.category,style,provider,undefined,project.artworks);s.addArtwork(base);}for(const entry of entries){const item=sharedGeometry?createSharedGeometryVariant(base!,style,entry):nameCollectionArt(await createArtworkWithProvider(entry.name,entry.prompt,entry.category,collectionStyle(style,entry.material),provider,undefined,project.artworks),entry);s.addArtwork(item);completed++;setCollectionProgress(completed+' / '+entries.length);}notify('Coleção gerada: '+completed+' variantes.');}catch(e){notify('Coleção interrompida em '+completed+' itens: '+String(e));}finally{setBusy(false);}};
const materialVariant=(material:typeof defaultMaterials[number])=>{if(!art)return;const copy=recolorMaterial(art,style,material);s.addArtwork(copy);notify('Variante criada: '+copy.name);};
const requestEdit=async()=>{if(!art||!editPrompt.trim())return;if(provider==='local-demo'){notify('Selecione Gemini ou OpenAI para edição por IA.');return;}if(editOnlySelected&&!shape){notify('Selecione uma camada para edição parcial.');return;}setBusy(true);try{const proposal=await proposeArtworkEdit(art,editPrompt,style,provider,editOnlySelected?shape?.id:null);setEditProposal(proposal);setEditOriginal(structuredClone(art));notify('Prévia pronta. Confira antes de aplicar.');}catch(e){notify('Erro: '+(e instanceof Error?e.message:String(e)));}finally{setBusy(false)}};
const approveEdit=()=>{if(!art||!editProposal||!editOriginal||art.id!==editProposal.artworkId)return;setEditUndo(structuredClone(art));s.commitArtworkEdit(applyEditProposal(art,editProposal),editPrompt.trim()||editProposal.summary);setEditProposal(null);setEditOriginal(null);setEditPrompt('');notify('Edição confirmada. É possível desfazer.');};
const undoEdit=()=>{if(!art||!editUndo||art.id!==editUndo.id)return;s.updateArtwork(()=>structuredClone(editUndo));setEditUndo(null);notify('Edição desfeita.');};
const importStyle=async(file:File)=>{try{const raw=JSON.parse(await file.text());const result=validateStyle(raw);if(!result.success){setStyleErrors(result.errors);notify('Arquivo inválido; veja os detalhes.');return;}s.setStyle(result.data);setStyleText(JSON.stringify(result.data,null,2));setStyleErrors([]);notify('Estilo importado e salvo como nova revisão.');}catch(e){notify(`Erro ao importar: ${String(e)}`)}};
const saveStyle=()=>{try{const result=validateStyle(JSON.parse(styleText));if(!result.success){setStyleErrors(result.errors);return;}s.setStyle(result.data);setStyleErrors([]);notify('Nova versão do estilo salva.')}catch(e){setStyleErrors([`JSON inválido: ${String(e)}`])}};
const beginDrag=(e:PointerEvent<SVGElement>,id:string)=>{const current=art?.shapes.find(x=>x.id===id);if(!current)return;const svg=e.currentTarget.ownerSVGElement; if(!svg)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const ctm=svg.getScreenCTM();if(!ctm)return;const pt=p.matrixTransform(ctm.inverse());const chosen=multiIds.includes(id)?multiIds:current.groupId?art!.shapes.filter(sh=>sh.groupId===current.groupId).map(sh=>sh.id):[id];const origins=Object.fromEntries(art!.shapes.filter(sh=>chosen.includes(sh.id)).map(sh=>[sh.id,{x:sh.x,y:sh.y}]));dragRef.current={id:current.id,x:current.x,y:current.y,startX:pt.x,startY:pt.y,origins};svg.setPointerCapture(e.pointerId)};
const moveDrag=(e:PointerEvent<SVGSVGElement>)=>{if(transformRef.current){const t=transformRef.current,svg=e.currentTarget,point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const cursor=point.matrixTransform(matrix.inverse());if(t.mode==='resize'){const dx=cursor.x-t.startX,dy=cursor.y-t.startY;s.updateShape(t.id,resizeShape(t.original,t.original.width+dx,t.original.height+dy));}else{const cx=t.original.x+t.original.width/2,cy=t.original.y+t.original.height/2;const start=Math.atan2(t.startY-cy,t.startX-cx),finish=Math.atan2(cursor.y-cy,cursor.x-cx);s.updateShape(t.id,{rotation:rotateShape(t.original,t.original.rotation+(finish-start)*180/Math.PI).rotation});}return;}if(nodeDragRef.current){const current=art?.shapes.find(sh=>sh.id===nodeDragRef.current!.id);if(!current?.d)return;const currentPoints=parseBezier(current.d);if(!currentPoints)return;const svg=e.currentTarget,pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const pos=pt.matrixTransform(matrix.inverse());const grid=(n:number)=>snapGrid?Math.round(n/8)*8:Math.round(n);let adjusted=currentPoints;const selected=activeNodes.includes(nodeDragRef.current.index)?activeNodes:[nodeDragRef.current.index];const currentPoint=currentPoints[nodeDragRef.current.index];const dx=grid(pos.x)-currentPoint.x,dy=grid(pos.y)-currentPoint.y;for(const index of selected){const pt=adjusted[index];if(pt)adjusted=moveBezierPointLinked(adjusted,index,pt.x+dx,pt.y+dy,mirrorHandles);}s.updateShape(current.id,{d:serializeBezier(adjusted)});return;}if(!dragRef.current)return;const svg=e.currentTarget,pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const ctm=svg.getScreenCTM();if(!ctm)return;const q=pt.matrixTransform(ctm.inverse()),d=dragRef.current;const dx=Math.round(q.x-d.startX),dy=Math.round(q.y-d.startY);s.updateArtwork(a=>({...a,shapes:a.shapes.map(sh=>d.origins[sh.id]?translateShape(sh,d.origins[sh.id].x+dx-sh.x,d.origins[sh.id].y+dy-sh.y):sh)}));};
const alignLayers=(axis:'x'|'y')=>{if(!art||multiIds.length<2)return;const shapes=art.shapes.filter(sh=>multiIds.includes(sh.id));const avg=shapes.reduce((a,sh)=>a+(axis==='x'?sh.x+sh.width/2:sh.y+sh.height/2),0)/shapes.length;const result={...art,shapes:art.shapes.map(sh=>!multiIds.includes(sh.id)?sh:{...sh,[axis]:Math.round(avg-(axis==='x'?sh.width:sh.height)/2)})};s.commitArtworkEdit(result,'Alinhar '+axis);};
const setGroup=(grouped:boolean)=>{if(!art||multiIds.length<2)return;const id=grouped?uid():undefined;s.commitArtworkEdit({...art,shapes:art.shapes.map(sh=>multiIds.includes(sh.id)?{...sh,groupId:id}:sh)},grouped?'Agrupar':'Desagrupar');};
const booleanAction=(operation:BooleanOperation)=>{if(!art)return;const picked=art.shapes.filter(sh=>multiIds.includes(sh.id));if(picked.length!==2){notify('Selecione exatamente duas camadas usando Shift + clique.');return;}try{const combined=combineShapes(picked,operation);const selected=new Set(picked.map(x=>x.id));s.commitArtworkEdit({...art,modifiedAt:now(),shapes:[...art.shapes.filter(sh=>!selected.has(sh.id)),combined]},'Operação booleana: '+operation);s.selectShape(combined.id);setMultiIds([]);notify('Operação vetorial aplicada.');}catch(e){notify('Erro de geometria: '+(e instanceof Error?e.message:String(e)));}};
const beginTransform=(e:PointerEvent<SVGElement>,mode:'resize'|'rotate')=>{if(!shape)return;e.stopPropagation();const svg=e.currentTarget.ownerSVGElement;if(!svg)return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const ctm=svg.getScreenCTM();if(!ctm)return;const pos=pt.matrixTransform(ctm.inverse());transformRef.current={id:shape.id,mode,startX:pos.x,startY:pos.y,original:structuredClone(shape)};svg.setPointerCapture(e.pointerId);};
const addBezier=()=>{s.addShape({id:uid(),name:'Curva Bézier',type:'path',x:100,y:100,width:310,height:260,fill:'none',stroke:style.outlines.color,strokeWidth:3,rotation:0,opacity:1,d:'M 100 350 C 180 100 320 100 410 350'});};
const commitNodes=(change:(pts:NonNullable<ReturnType<typeof parseBezier>>)=>NonNullable<ReturnType<typeof parseBezier>>)=>{if(!shape?.d)return;const pts=parseBezier(shape.d);if(!pts)return;const newD=serializeBezier(change(pts));if(newD===shape.d)return;setNodeUndo(v=>[...v,shape.d!].slice(-40));setNodeRedo([]);s.updateShape(shape.id,{d:newD});};
const nodeStep=(undo:boolean)=>{if(!shape?.d)return;const stack=undo?nodeUndo:nodeRedo;const previous=stack[stack.length-1];if(previous===undefined)return;if(undo){setNodeUndo(v=>v.slice(0,-1));setNodeRedo(v=>[...v,shape.d!]);}else{setNodeRedo(v=>v.slice(0,-1));setNodeUndo(v=>[...v,shape.d!]);}s.updateShape(shape.id,{d:previous});};
const endDrag=()=>{if(nodeDragRef.current&&shape?.d&&nodeDragRef.current.id===shape.id&&shape.d!==nodeDragRef.current.startD){setNodeUndo(h=>[...h,nodeDragRef.current!.startD].slice(-40));setNodeRedo([]);}dragRef.current=null;nodeDragRef.current=null;transformRef.current=null};
if(!project)return <main className="empty-app"><h1>AI Vectorial Studio</h1><p>Crie um projeto para começar.</p><button className="primary" onClick={()=>setModal('project')}>Criar projeto</button>{modal==='project'&&<button onClick={()=>s.createProject('Novo projeto',defaultStyle)}>Confirmar</button>}</main>;
return <div className="app-shell"><header className="topbar"><div className="brand"><div className="brand-icon"><Shapes size={22}/></div><div><strong>AI Vectorial <span>Studio</span></strong><small>CREATIVE WORKSPACE</small></div></div><div className="project-picker"><Folder size={16}/><select value={project.id} onChange={e=>s.selectProject(e.target.value)}>{s.projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><button className="icon-button" title="Criar projeto" onClick={()=>setModal('project')}><Plus size={17}/></button></div><div className="header-right"><span className="autosave"><CheckCircle2 size={14}/> Salvamento automático</span><span className="version">BETA · v0.1</span></div></header><aside className="sidebar"><div className="sidebar-label">WORKSPACE</div><button className={`nav ${tab==='create'?'active':''}`} onClick={()=>setTab('create')}><Paintbrush size={18}/> Criar arte</button><button className={`nav ${tab==='style'?'active':''}`} onClick={()=>{setTab('style');setStyleText(JSON.stringify(project.style,null,2))}}><PaletteIcon/> Estilo do projeto</button><button className={`nav ${tab==='library'?'active':''}`} onClick={()=>setTab('library')}><ImageIcon size={18}/> Biblioteca <span className="count">{project.artworks.length}</span></button><div className="sidebar-label section-spacer">PROJETO</div><div className="project-description"><strong>{project.name}</strong><span>{project.description||'Projeto independente'}</span></div><div className="style-mini"><span className="tiny-label">ESTILO ATIVO</span><strong>{project.style.name}</strong><div className="swatches">{project.style.palette.primary.concat(project.style.palette.secondary).map((c,i)=><span key={i} style={{background:c}}/>)}</div><small>Versão {project.style.version}</small></div><div className="sidebar-bottom"><button className="subtle" onClick={()=>setModal('styles')}><Plus size={15}/> Novo estilo / duplicar</button><button className="subtle" onClick={()=>saveJson(project,`${project.name.replaceAll(' ','-')}-backup.json`)}><Download size={15}/> Backup do projeto</button></div></aside>
<main className="workspace">{tab==='create'?<><section className="workspace-heading"><div><span className="eyebrow">VECTOR CREATION</span><h1>Estúdio de criação</h1><p>Transforme ideias em ilustrações vetoriais editáveis.</p></div><div className="heading-actions"><button className="secondary" onClick={()=>{const empty:Artwork={id:uid(),name:'Nova ilustração',prompt:'',category,createdAt:now(),modifiedAt:now(),size:512,shapes:[],stylePatch:{}};s.addArtwork(empty)}}><Plus size={16}/> Tela em branco</button></div></section><section className="studio-layout"><div className="left-stack"><div className="panel prompt-panel"><div className="panel-title"><div><Paintbrush size={17}/><strong>Gerar arte</strong></div><span className="pill">VETORIAL</span></div><label>Motor de geração</label><select value={provider} onChange={e=>setProvider(e.target.value as GeneratorId)}><option value="local-demo">Procedural (demonstração)</option><option value="openai">OpenAI (arte SVG por IA)</option><option value="gemini">Google Gemini (SVG por IA)</option></select><label>Nome da ilustração</label><input value={artName} onChange={e=>setArtName(e.target.value)} placeholder="Nome"/><label>Categoria</label><select value={category} onChange={e=>setCategory(e.target.value)}><option value="weapons">Armas e ferramentas</option><option value="items">Itens e objetos</option><option value="icons">Ícones</option><option value="characters">Personagens</option><option value="environment">Cenários</option><option value="custom">Personalizado</option></select><div className="tabs"><button className={inputMode==='prompt'?'selected':''} onClick={()=>setInputMode('prompt')}>Prompt</button><button className={inputMode==='json'?'selected':''} onClick={()=>setInputMode('json')}>{'{ }'} JSON</button></div>{inputMode==='prompt'?<><label>Descreva sua criação</label><textarea className="prompt-input" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Descreva o objeto..."/><p className="helper">{provider!=='local-demo'?'A IA recebe o style.json ativo. Configure GEMINI_API_KEY ou OPENAI_API_KEY no .env.local do servidor Vite.':'Modo procedural: reconhece espada, escudo, poção, machado e estrela. Outros prompts geram composição genérica.'}</p></>:<><label>Formas estruturadas</label><textarea className="json-input" spellCheck={false} value={json} onChange={e=>setJson(e.target.value)}/><p className="helper">Tipos: rect, ellipse, path e polygon. Coordenadas na área 512 × 512.</p></>}<div className="style-reference"><div className="style-ref-top"><span>Usando estilo do projeto</span><strong>{project.style.name}</strong></div><div className="swatches">{project.style.palette.primary.map((c,i)=><span key={i} style={{background:c}}/>)}</div></div><button className="primary generate" onClick={generate} disabled={busy}><Shapes size={18}/>{busy?'Gerando...':'Gerar ilustração vetorial'}</button></div><div className="panel asset-list"><div className="panel-title"><div><Layers size={17}/><strong>Ilustrações</strong></div><span className="count">{project.artworks.length}</span></div><div className="art-list">{project.artworks.length?project.artworks.map(a=><button key={a.id} className={`art-row ${a.id===art?.id?'chosen':''}`} onClick={()=>s.selectArtwork(a.id)}><span className="small-thumb"><Preview art={a} small/></span><span><strong>{a.name}</strong><small>{a.category} · {a.shapes.length} camadas</small></span></button>):<p className="empty-list">As artes geradas aparecerão aqui.</p>}</div></div></div><div className="editor-column"><div className="panel canvas-panel"><div className="canvas-toolbar"><div><strong>Canvas</strong><span>512 × 512 px</span></div><div className="toolbar-actions"><button title="Grade" className={showGrid?'tool-on':''} onClick={()=>setShowGrid(!showGrid)}><Grid3X3 size={16}/></button><button title="Reduzir zoom" onClick={()=>setZoom(Math.max(40,zoom-20))}><ZoomOut size={16}/></button><span>{zoom}%</span><button title="Aumentar zoom" onClick={()=>setZoom(Math.min(180,zoom+20))}><ZoomIn size={16}/></button></div></div><div className={`canvas-background ${showGrid?'grid-bg':''}`}><div className="canvas-paper" style={{width:`${Math.min(620,zoom*5.12)}px`,height:`${Math.min(620,zoom*5.12)}px`}}>{art?<svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" className="art-canvas-svg" onPointerMove={moveDrag} onPointerUp={endDrag} onLostPointerCapture={endDrag} onClick={()=>s.selectShape(null)}><g dangerouslySetInnerHTML={{__html:textureDefs(art.shapes.filter(sh=>sh.texture).map(sh=>({texture:sh.texture!,fill:sh.fill})))}}/>{art.shapes.map(sh=><SvgShape key={sh.id} s={sh} selected={sh.id===shape?.id||multiIds.includes(sh.id)} onSelect={()=>s.selectShape(sh.id)} onBegin={beginDrag}/>)}{nodeMode&&shape?.type==='path'&&shape.d&&shape.rotation===0&&parseBezier(shape.d)&&<g className="bezier-overlay">{(()=>{const pts=parseBezier(shape.d)!;return <>{pts.map((p,i)=>p.kind==='control'&&<line key={'guide'+i} x1={i%3===1?pts[i-1].x:pts[i+1].x} y1={i%3===1?pts[i-1].y:pts[i+1].y} x2={p.x} y2={p.y} stroke="#FFD277" strokeWidth={1.5} strokeDasharray="4 3" pointerEvents="none"/>)}{pts.map((p,i)=><circle key={'node'+i} cx={p.x} cy={p.y} r={p.kind==='anchor'?7:5} fill={p.kind==='anchor'?'#72B5FF':'#FFD277'} stroke="#152235" strokeWidth={2} style={{cursor:'grab'}} onPointerDown={e=>{e.stopPropagation();if(e.shiftKey)setActiveNodes(v=>v.includes(i)?v.filter(n=>n!==i):[...v,i]);else setActiveNodes([i]);nodeDragRef.current={id:shape.id,index:i,startD:shape.d||''};e.currentTarget.ownerSVGElement?.setPointerCapture(e.pointerId)}}/>)}</>})()}</g>}{transformMode&&shape&&<g className="transform-overlay"><rect x={shape.x} y={shape.y} width={shape.width} height={shape.height} fill="none" stroke="#64C5FF" strokeDasharray="5 4" strokeWidth={1.7} pointerEvents="none"/><rect x={shape.x+shape.width-7} y={shape.y+shape.height-7} width={14} height={14} fill="#64C5FF" stroke="#142033" strokeWidth={2} style={{cursor:'nwse-resize'}} onPointerDown={e=>beginTransform(e,'resize')}/><line x1={shape.x+shape.width/2} y1={shape.y} x2={shape.x+shape.width/2} y2={shape.y-32} stroke="#64C5FF" pointerEvents="none"/><circle cx={shape.x+shape.width/2} cy={shape.y-32} r={8} fill="#64C5FF" stroke="#142033" strokeWidth={2} style={{cursor:'grab'}} onPointerDown={e=>beginTransform(e,'rotate')}/></g>}</svg>:<div className="canvas-placeholder"><Shapes size={55}/><strong>Sua próxima criação começa aqui</strong><span>Escreva um prompt e clique em gerar</span></div>}</div></div><div className="canvas-footer"><span><MousePointer2 size={14}/> Selecione e arraste as camadas</span><span>{art?`${art.shapes.length} objetos SVG`:'Nenhuma ilustração selecionada'}</span></div></div>{art&&<div className="panel export-panel"><div className="panel-title"><div><Download size={17}/><strong>Exportar ilustração</strong></div></div><div className="export-row"><select value={pngSize} onChange={e=>setPngSize(Number(e.target.value))}><option value={256}>256 × 256</option><option value={512}>512 × 512</option><option value={1024}>1024 × 1024</option><option value={2048}>2048 × 2048</option></select><label className="checkbox-label"><input type="checkbox" checked={transparent} onChange={e=>setTransparent(e.target.checked)}/> Fundo transparente</label></div><div className="export-buttons"><button className="secondary" onClick={()=>exportSvg(art)}><Code size={16}/> SVG editável</button><button className="secondary" onClick={()=>exportPng(art,pngSize,transparent).catch(e=>notify(String(e)))}><ImageIcon size={16}/> PNG</button></div></div>}</div><div className="right-stack">{art&&<div className="panel"><div className="panel-title"><div><Paintbrush size={17}/><strong>Editar com IA</strong></div><span className="pill">BETA</span></div><p className="subcopy">Use Gemini ou OpenAI para alterar a arte sem regenerar tudo. A IA propõe mudanças apenas nas propriedades das camadas existentes.</p><textarea rows={4} value={editPrompt} onChange={e=>{setEditPrompt(e.target.value);setEditProposal(null);setEditOriginal(null)}} placeholder="Ex.: deixe a lâmina azul e aumente seu brilho"/><label className="checkbox-label"><input type="checkbox" checked={editOnlySelected} onChange={e=>{setEditOnlySelected(e.target.checked);setEditProposal(null);setEditOriginal(null)}}/> Editar só a camada selecionada</label><p className="helper">Motor ativo: {provider==='gemini'?'Gemini':provider==='openai'?'OpenAI':'Procedural (selecione IA)'}</p><button className="primary" disabled={busy||!editPrompt.trim()||provider==='local-demo'||(editOnlySelected&&!shape)} onClick={()=>void requestEdit()}>{busy?'Aguarde...':'Gerar prévia da edição'}</button>{editProposal&&editOriginal&&art.id===editProposal.artworkId&&<div><p><strong>Prévia:</strong> {editProposal.summary}</p><p className="helper">{editProposal.changes.length} modificada(s), {editProposal.additions.length} adicionada(s), {editProposal.removals.length} removida(s)</p><div className="export-row"><div><small>Antes</small><Preview art={editOriginal} small/></div><div><small>Depois</small><Preview art={applyEditProposal(editOriginal,editProposal)} small/></div></div><div className="export-buttons"><button className="primary" onClick={approveEdit}>Aceitar</button><button className="secondary" onClick={()=>{setEditProposal(null);setEditOriginal(null)}}>Cancelar</button></div></div>}{editUndo&&editUndo.id===art.id&&<button className="secondary" onClick={undoEdit}><RotateCcw size={15}/> Desfazer última edição IA</button>}</div>}{art&&<div className="panel"><div className="panel-title"><div><History size={17}/><strong>Histórico da arte</strong></div><span>{project.artworkHistory?.[art.id]?.length||0}</span></div><p className="subcopy">Até 30 revisões salvas no projeto. Restaurar preserva uma cópia da versão atual.</p><div className="revisions">{[...(project.artworkHistory?.[art.id]||[])].reverse().map(r=><div className="revision" key={r.id}><span><strong>{r.label}</strong><small>{new Date(r.createdAt).toLocaleString('pt-BR')}</small></span><button title="Restaurar revisão" onClick={()=>{s.restoreArtworkRevision(r.id);setEditProposal(null);setEditOriginal(null);notify('Revisão restaurada.')}}><RotateCcw size={15}/></button></div>)}</div></div>}<div className="panel"><div className="panel-title"><div><Shapes size={17}/><strong>Editor vetorial</strong></div></div><div className="export-buttons"><button className="secondary" disabled={!shape||shape.type!=='path'} onClick={()=>setNodeMode(v=>!v)}>{nodeMode?'Desativar nós':'Editar nós no canvas'}</button></div>{nodeMode&&shape?.type==='path'&&<><div className="export-buttons"><button className="secondary" onClick={()=>commitNodes(p=>addBezierNode(p,Math.max(0,Math.floor((activeNodes[0]||0)/3))))}>Adicionar nó</button><button className="secondary" onClick={()=>commitNodes(p=>removeBezierAnchor(p,activeNodes.find(i=>i%3===0)??-1))}>Remover nó</button><button className="secondary" onClick={()=>commitNodes(p=>closeBezier(p))}>Fechar caminho</button></div><div className="export-buttons"><button className="secondary" onClick={()=>commitNodes(p=>setBezierSmooth(p,activeNodes.find(i=>i%3===0)??-1,true))}>Suavizar nó</button><button className="secondary" onClick={()=>commitNodes(p=>setBezierSmooth(p,activeNodes.find(i=>i%3===0)??-1,false))}>Criar canto</button><button className="secondary" disabled={!nodeUndo.length} onClick={()=>nodeStep(true)}>Desfazer</button><button className="secondary" disabled={!nodeRedo.length} onClick={()=>nodeStep(false)}>Refazer</button></div><label className="checkbox-label"><input type="checkbox" checked={snapGrid} onChange={e=>setSnapGrid(e.target.checked)}/> Encaixar nós à grade de 8 px</label><label className="checkbox-label"><input type="checkbox" checked={mirrorHandles} onChange={e=>setMirrorHandles(e.target.checked)}/> Espelhar alças opostas</label><p className="helper">Shift + clique para selecionar vários nós. {activeNodes.length} selecionado(s).</p></>}{nodeMode&&<p className="helper">Arraste nós azuis ou alças amarelas. Compatível com curvas M/C absolutas sem rotação.</p>}<p className="subcopy">Shift + clique nas camadas para selecionar várias.</p><div className="export-buttons"><button className="secondary" disabled={!art} onClick={addBezier}>+ Curva Bézier</button><button className="secondary" onClick={()=>setMultiIds([])}>Limpar seleção</button></div><p className="helper">{multiIds.length} camadas selecionadas</p><div className="export-buttons"><button className="secondary" disabled={multiIds.length<2} onClick={()=>setGroup(true)}>Agrupar</button><button className="secondary" disabled={multiIds.length<2} onClick={()=>setGroup(false)}>Desagrupar</button></div><div className="export-buttons"><button className="secondary" disabled={multiIds.length<2} onClick={()=>alignLayers('x')}>Alinhar X</button><button className="secondary" disabled={multiIds.length<2} onClick={()=>alignLayers('y')}>Alinhar Y</button></div></div><div className="panel"><div className="panel-title"><div><Move size={17}/><strong>Transformar no canvas</strong></div></div><p className="subcopy">Selecione uma forma e arraste a alça do canto para escalar ou a alça superior para girar.</p><button className="secondary" disabled={!shape} onClick={()=>setTransformMode(v=>!v)}>{transformMode?'Desativar transformações':'Ativar escala e rotação'}</button></div><div className="panel"><div className="panel-title"><div><Shapes size={17}/><strong>Operações booleanas</strong></div></div><p className="subcopy">Selecione duas camadas com Shift + clique. A primeira determina o preenchimento e o contorno do resultado.</p><div className="export-buttons">{(['union','subtract','intersect','exclude'] as const).map(op=><button key={op} className="secondary" disabled={multiIds.length!==2} onClick={()=>booleanAction(op)}>{({union:'Unir',subtract:'Subtrair',intersect:'Interseção',exclude:'Excluir sobreposição'} as const)[op]}</button>)}</div></div><div className="panel"><div className="panel-title"><div><Layers size={17}/><strong>Produção em lote</strong></div></div><p className="subcopy">Uma descrição por linha, até 24 artes. Usa o motor e o estilo ativos.</p><textarea rows={5} value={batchText} onChange={e=>setBatchText(e.target.value)}/><button className="primary" disabled={busy||!batchText.trim()} onClick={()=>void generateBatch()}>{busy?'Gerando lote…':'Gerar coleção'}</button>{batchMessage&&<p className="helper">Progresso: {batchMessage}</p>}{art&&<><p className="subcopy">Criar variante da arte atual por material:</p><div className="export-buttons">{defaultMaterials.map(m=><button key={m.name} className="secondary" disabled={busy} onClick={()=>materialVariant(m)}>{m.name}</button>)}</div></>}</div><div className="panel"><div className="panel-title"><div><Download size={17}/><strong>Exportar atlas</strong></div></div><p className="subcopy">Inclui todas as artes do projeto como frames em PNG transparente e metadados JSON.</p><div className="property-grid"><label>Frame (px)<select value={atlasSize} onChange={e=>setAtlasSize(Number(e.target.value))}>{[128,179,256,512].map(v=><option value={v} key={v}>{v}</option>)}</select></label><label>Colunas<input type="number" min={1} max={16} value={atlasColumns} onChange={e=>setAtlasColumns(Number(e.target.value))}/></label><label>Padding<input type="number" min={0} max={64} value={atlasPadding} onChange={e=>setAtlasPadding(Number(e.target.value))}/></label></div><button className="secondary" disabled={!project.artworks.length||busy} onClick={()=>void exportAtlas(project.artworks,atlasSize,atlasColumns,atlasPadding).catch(e=>notify(String(e)))}>Exportar PNG + JSON</button></div><div className="panel"><div className="panel-title"><div><Shapes size={17}/><strong>Coleções inteligentes</strong></div></div><p className="subcopy">Crie famílias de assets combinando materiais e raridades com as mesmas orientações de geometria e estilo.</p><label>Template</label><select value={collectionPreset} onChange={e=>{const p=templatePresets.find(x=>x.id===e.target.value);setCollectionPreset(e.target.value);if(p){setCollectionMaterials(p.materials);setCollectionRarities(p.rarities);setCollectionPrompt(p.basePrompt);}}}>{templatePresets.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><label>Descrição base</label><textarea rows={3} value={collectionPrompt} placeholder={templatePresets.find(p=>p.id===collectionPreset)?.basePrompt} onChange={e=>setCollectionPrompt(e.target.value)}/><p className="helper">Materiais</p><div className="export-buttons">{defaultMaterials.map(m=><label key={m.name} className="checkbox-label"><input type="checkbox" checked={collectionMaterials.includes(m.name)} onChange={e=>setCollectionMaterials(v=>e.target.checked?[...v,m.name]:v.filter(x=>x!==m.name))}/>{m.name}</label>)}</div><p className="helper">Raridades</p><div className="export-buttons">{rarityLevels.map(level=><label key={level} className="checkbox-label"><input type="checkbox" checked={collectionRarities.includes(level)} onChange={e=>setCollectionRarities(v=>e.target.checked?[...v,level]:v.filter(x=>x!==level))}/>{level}</label>)}</div><label className="checkbox-label"><input type="checkbox" checked={sharedGeometry} onChange={e=>setSharedGeometry(e.target.checked)}/> Preservar geometria: gerar apenas um modelo-base</label>{sharedGeometry&&<><label>Arte-base (opcional)</label><select value={baseArtworkId} onChange={e=>setBaseArtworkId(e.target.value)}><option value="">Gerar modelo-base automaticamente</option>{project.artworks.filter(a=>a.shapes.length>0).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><p className="helper">As variantes reaproveitam exatamente a geometria e as proporções do modelo, com paletas de material e raridade. A geração automática faz apenas uma chamada de IA.</p></>}<button className="primary" disabled={busy||!collectionMaterials.length||!collectionRarities.length} onClick={()=>void generateCollection()}>{busy?'Gerando...':'Gerar variantes da coleção'}</button>{collectionProgress&&<p className="helper">Progresso: {collectionProgress}</p>}</div><div className="panel"><div className="panel-title"><div><Paintbrush size={17}/><strong>Materiais vetoriais</strong></div></div><p className="subcopy">Aplique uma textura SVG repetível à camada selecionada. As cores originais são preservadas e o padrão acompanha o formato da peça.</p><select disabled={!shape} value={shape?.texture?.kind||''} onChange={e=>{if(!shape)return;const kind=e.target.value as 'wood'|'metal'|'stone'|'fabric';s.updateShape(shape.id,{texture:kind?{kind,scale:1,intensity:.5}:undefined});}}><option value="">Sem textura</option>{texturePresets.map(p=><option key={p.kind} value={p.kind}>{p.label}</option>)}</select>{shape?.texture&&<><label>Escala da textura<input type="range" min=".4" max="4" step=".1" value={shape.texture.scale} onChange={e=>s.updateShape(shape.id,{texture:{...shape.texture!,scale:Number(e.target.value)}})}/></label><label>Intensidade<input type="range" min="0" max="1" step=".05" value={shape.texture.intensity} onChange={e=>s.updateShape(shape.id,{texture:{...shape.texture!,intensity:Number(e.target.value)}})}/></label></>}</div><div className="panel layers-panel"><div className="panel-title"><div><Layers size={17}/><strong>Camadas</strong></div><span>{art?.shapes.length||0}</span></div>{art?<div className="layers-list">{[...art.shapes].reverse().map(sh=><button key={sh.id} className={`layer-row ${shape?.id===sh.id?'chosen':''}`} onClick={e=>{if(e.shiftKey)setMultiIds(ids=>ids.includes(sh.id)?ids.filter(id=>id!==sh.id):[...ids,sh.id]);else s.selectShape(sh.id)}}><Shapes size={15}/><span>{sh.name}</span><small>{sh.type}</small></button>)}</div>:<div className="empty-side"><Layers size={27}/><span>Selecione uma arte para editar suas camadas.</span></div>}{art&&<div className="layer-bottom"><button onClick={()=>{const sh:VectorShape={id:uid(),name:'Novo retângulo',type:'rect',x:170,y:170,width:150,height:150,fill:style.palette.primary[0],stroke:style.outlines.color,strokeWidth:style.outlines.width,rotation:0,opacity:1};s.addShape(sh)}}><Plus size={15}/> Adicionar</button>{shape&&<button onClick={()=>s.removeShape(shape.id)}><Trash2 size={15}/></button>}</div>}</div><div className="panel properties-panel"><div className="panel-title"><div><Move size={17}/><strong>Propriedades</strong></div></div>{shape?<><label>Nome</label><input value={shape.name} onChange={e=>s.updateShape(shape.id,{name:e.target.value})}/><div className="property-grid">{(['x','y','width','height','rotation','opacity'] as const).map(key=><label key={key}>{key.toUpperCase()}<input type="number" step={key==='opacity'?0.1:1} min={key==='opacity'?0:undefined} max={key==='opacity'?1:undefined} value={shape[key]} onChange={e=>s.updateShape(shape.id,{[key]:Number(e.target.value)})}/></label>)}</div><div className="property-grid"><label>Preenchimento<input type="color" value={shape.fill.startsWith('#')?shape.fill:'#888888'} onChange={e=>s.updateShape(shape.id,{fill:e.target.value})}/></label><label>Contorno<input type="color" value={shape.stroke.startsWith('#')?shape.stroke:'#111111'} onChange={e=>s.updateShape(shape.id,{stroke:e.target.value})}/></label></div>{shape.type==='path'&&<><label>Caminho SVG (d)</label><textarea rows={4} value={shape.d||''} onChange={e=>s.updateShape(shape.id,{d:e.target.value})}/><p className="helper">Edite M, L, C, Q e Z para ajustar a curva.</p></>}{shape.type==='polygon'&&<><label>Pontos do polígono</label><textarea rows={3} value={shape.points||''} onChange={e=>s.updateShape(shape.id,{points:e.target.value})}/></>}<label>Espessura do contorno<input type="number" min="0" max="40" value={shape.strokeWidth} onChange={e=>s.updateShape(shape.id,{strokeWidth:Number(e.target.value)})}/></label><div className="property-actions"><button className="secondary" onClick={()=>{const name=window.prompt('Nome do componente',shape.name);if(name){s.saveComponent(name);notify('Componente salvo na biblioteca.')}}}><Save size={15}/> Salvar componente</button><button className="secondary" onClick={()=>s.addShape({...structuredClone(shape),id:uid(),name:`${shape.name} cópia`,x:shape.x+18,y:shape.y+18})}><Copy size={15}/> Duplicar</button></div></>:<div className="empty-side"><MousePointer2 size={25}/><span>Selecione uma camada no canvas.</span></div>}</div><div className="panel"><div className="panel-title"><div><Box size={17}/><strong>Biblioteca de componentes</strong></div></div><p className="subcopy">Reutilize ornamentos, equipamentos e partes de personagens. Shift + clique permite selecionar várias camadas.</p><label>Nome</label><input value={componentName} onChange={e=>setComponentName(e.target.value)}/><label>Categoria</label><select value={componentCategory} onChange={e=>setComponentCategory(e.target.value)}>{['Ornamentos','Armas','Armaduras','Personagens','Cenários','Outros'].map(c=><option key={c}>{c}</option>)}</select><label>Tags separadas por vírgula</label><input value={componentTags} onChange={e=>setComponentTags(e.target.value)}/><button className="secondary" disabled={!art||(!shape&&!multiIds.length)} onClick={()=>{s.saveComponent(componentName,multiIds.length?multiIds:shape?[shape.id]:[],componentCategory,componentTags.split(','));notify('Componente salvo.');}}>Salvar camadas selecionadas</button><button className="secondary" disabled={!art} onClick={()=>{if(!art)return;const suggestions=recommendComponents(project.components,art.name+' '+art.prompt+' '+art.category);if(!suggestions.length){notify('Nenhum componente compatível encontrado pelas tags.');return;}suggestions.forEach((c,i)=>s.insertComponent(c.id,{x:180+i*24,y:180+i*24,linked:true}));notify(suggestions.length+' componente(s) reutilizado(s).');}}>Sugerir componentes compatíveis</button><label>Buscar na biblioteca</label><input placeholder="Nome, categoria ou tags" value={componentSearch} onChange={e=>setComponentSearch(e.target.value)}/><div className="property-grid"><label>Escala<input type="number" min={0.05} max={8} step={0.1} value={componentScale} onChange={e=>setComponentScale(Number(e.target.value))}/></label><label>Rotação<input type="number" value={componentRotation} onChange={e=>setComponentRotation(Number(e.target.value))}/></label></div><label className="checkbox-label"><input type="checkbox" checked={componentLinked} onChange={e=>setComponentLinked(e.target.checked)}/> Instância vinculada</label><label className="checkbox-label"><input type="checkbox" checked={componentFlip} onChange={e=>setComponentFlip(e.target.checked)}/> Espelhar horizontalmente</label>{project.components.filter(c=>(c.name+' '+(c.category||'')+' '+(c.tags||[]).join(' ')).toLowerCase().includes(componentSearch.toLowerCase())).map(c=><div className="component-row" key={c.id}><strong>{c.name}</strong><small>{c.category||'Outros'} · v{c.version||1}</small><div className="export-buttons"><select value={componentSocket} onChange={e=>setComponentSocket(e.target.value)}><option value="">Sem socket</option>{(c.sockets||[]).map(socket=><option key={socket.name} value={socket.name}>{socket.name}</option>)}</select></div><div className="export-buttons"><input placeholder="Nome do socket" value={socketName} onChange={e=>setSocketName(e.target.value)}/><input type="number" title="Socket X" value={socketX} onChange={e=>setSocketX(Number(e.target.value))}/><input type="number" title="Socket Y" value={socketY} onChange={e=>setSocketY(Number(e.target.value))}/><button className="secondary" onClick={()=>{try{s.addComponentSocket(c.id,socketName,socketX,socketY);}catch(error){notify(String(error));}}}>Salvar encaixe</button></div><div className="export-buttons"><button className="secondary" disabled={!art} onClick={()=>s.insertComponent(c.id,{scale:componentScale,rotation:componentRotation,flipX:componentFlip,linked:componentLinked,socket:componentSocket||undefined})}>Inserir</button><button className="secondary" disabled={!art||!shape} onClick={()=>{if(!art||!shape)return;const selection=art.shapes.filter(sh=>(multiIds.length?multiIds:[shape.id]).includes(sh.id));if(!selection.length)return;s.updateComponent(c.id,selection);notify('Componente atualizado e instâncias sincronizadas.');}}>Atualizar modelo</button></div></div>)}{shape?.componentId&&<button className="secondary" onClick={()=>s.detachComponent(shape.id)}>Desvincular camada</button>}<div className="export-buttons"><button className="secondary" onClick={()=>saveJson(componentPackage(project.components),'componentes-aivs.json')}>Exportar biblioteca</button><label className="secondary" style={{cursor:'pointer'}}>Importar biblioteca<input hidden type="file" accept=".json,application/json" onChange={e=>{const file=e.target.files?.[0];if(file)void file.text().then(t=>{try{s.importComponents(JSON.parse(t));notify('Biblioteca importada.');}catch(error){notify(String(error));}});e.target.value='';}}/></label></div></div></div></section></>:tab==='style'?<><section className="workspace-heading"><div><span className="eyebrow">ART DIRECTION</span><h1>Identidade visual</h1><p>O estilo define a linguagem visual, independentemente do objeto gerado.</p></div><button className="secondary" onClick={()=>saveJson(project.style,'style.json')}><Download size={16}/> Exportar style.json</button></section><section className="style-layout"><div className="panel"><div className="panel-title"><div><Paintbrush size={18}/><strong>Editor de style.json</strong></div><span className="pill">SCHEMA 1.0</span></div><p className="subcopy">Edite os valores abaixo. As propriedades são validadas com Zod e alterações geram uma revisão imutável.</p><textarea className="style-editor" value={styleText} spellCheck={false} onChange={e=>setStyleText(e.target.value)}/>{styleErrors.length>0&&<div className="error-list"><AlertCircle size={17}/><div>{styleErrors.map((e,i)=><div key={i}>{e}</div>)}</div></div>}<div className="style-actions"><button className="primary" onClick={saveStyle}><Save size={16}/> Salvar nova revisão</button><button className="secondary" onClick={()=>importRef.current?.click()}><Upload size={16}/> Importar JSON</button><input hidden ref={importRef} type="file" accept="application/json,.json" onChange={e=>{const f=e.target.files?.[0];if(f)void importStyle(f);e.target.value=''}}/></div></div><div className="style-side"><div className="panel"><div className="panel-title"><div><Paintbrush size={17}/><strong>Prévia do estilo</strong></div></div><div className="style-cover"><div className="swatches large">{project.style.palette.primary.concat(project.style.palette.secondary,[project.style.palette.highlight,project.style.palette.shadow]).map((c,i)=><span key={i} title={c} style={{background:c}}/>)}</div><h3>{project.style.name}</h3><p>{project.style.description}</p><div className="style-spec"><span>Tema</span><strong>{project.style.artDirection.theme}</strong><span>Perspectiva</span><strong>{project.style.composition.perspective}</strong><span>Complexidade</span><strong>{project.style.artDirection.complexity*100}%</strong></div></div></div><div className="panel"><div className="panel-title"><div><History size={17}/><strong>Histórico de versões</strong></div></div><p className="subcopy">Restaurar cria uma nova revisão sem apagar as anteriores.</p><div className="revisions">{[...project.styleRevisions].reverse().map((r,i)=><div className="revision" key={r.id}><span><strong>{r.style.name}</strong><small>v{r.style.version} · {new Date(r.createdAt).toLocaleString('pt-BR')}</small></span><button disabled={i===0} title="Restaurar versão" onClick={()=>{s.restoreRevision(r.id);setStyleText(JSON.stringify(r.style,null,2));notify('Versão restaurada em nova revisão.')}}><RotateCcw size={15}/></button></div>)}</div></div></div></section></>:<><section className="workspace-heading"><div><span className="eyebrow">ASSET LIBRARY</span><h1>Biblioteca de artes</h1><p>Todas as ilustrações pertencem exclusivamente a este projeto.</p></div><button className="secondary" onClick={()=>setTab('create')}><Plus size={16}/> Nova arte</button></section><div className="gallery">{project.artworks.map(a=><div key={a.id} className="gallery-card"><div className="gallery-preview" onClick={()=>{s.selectArtwork(a.id);setTab('create')}}><Preview art={a}/></div><div className="gallery-info"><strong>{a.name}</strong><small>{a.category} · {a.shapes.length} camadas</small><div><button onClick={()=>{s.selectArtwork(a.id);setTab('create')}}>Editar</button><button onClick={()=>exportSvg(a)} title="Exportar"><Download size={15}/></button><button onClick={()=>{if(confirm(`Excluir ${a.name}?`))s.deleteArtwork(a.id)}} title="Excluir"><Trash2 size={15}/></button></div></div></div>)}{project.artworks.length===0&&<p className="empty-gallery">Sua biblioteca está vazia. Crie uma ilustração para começar.</p>}</div></>}</main>
{modal&&<div className="modal-backdrop" onClick={()=>setModal(null)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="panel-title"><div><Folder size={18}/><strong>{modal==='project'?'Criar projeto':'Criar estilo'}</strong></div><button onClick={()=>setModal(null)}>×</button></div>{modal==='project'?<><label>Nome do projeto</label><input value={newProjectName} onChange={e=>setNewProjectName(e.target.value)}/><label>Estilo inicial</label><select value={presetIndex} onChange={e=>setPresetIndex(Number(e.target.value))}>{stylePresets.map((p,i)=><option value={i} key={p.id}>{p.name}</option>)}</select><p className="subcopy">Cada projeto terá sua própria cópia do estilo e suas próprias artes.</p><button className="primary" onClick={()=>{s.createProject(newProjectName||'Novo projeto',structuredClone(stylePresets[presetIndex]));setModal(null);setTab('create')}}>Criar projeto</button></>:<><p className="subcopy">Duplicar o estilo atual como nova revisão editável. Um estilo também pode ser exportado e importado em outro projeto.</p><button className="primary" onClick={()=>{s.setStyle({...structuredClone(project.style),id:uid(),name:`${project.style.name} (cópia)`,version:'1.0.0'});setModal(null);setTab('style');setStyleText(JSON.stringify({...project.style,name:`${project.style.name} (cópia)`},null,2))}}>Duplicar estilo atual</button></>}</div></div>}{message&&<div className="toast"><CheckCircle2 size={17}/>{message}</div>}</div>}
function PaletteIcon(){return <Paintbrush size={18}/>}
